    if out.returncode:
        print("YAML invalid:", out.stderr[-200:]); sys.exit(1)
    return json.loads(out.stdout)

FENCE = re.compile(r"^\s*(`{3,}|~{3,})")
def prose(text):
    keep, fence = [], None
    for line in text.splitlines():
        m = FENCE.match(line)
        if m:
            fence = None if fence and m.group(1)[0] == fence else (fence or m.group(1)[0])
            continue
        if not fence:
            keep.append(line)
    return "\n".join(keep)
def slug(h):
    t = re.sub(r"`([^`]*)`", r"\1", h.strip().lower())
    t = re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", t)
    return re.sub(r"[^\w\- ]", "", t).replace(" ", "-")
def anchors(path):
    return {slug(m.group(2)) for m in re.finditer(r"^(#{1,6})\s+(.+?)\s*#*\s*$", prose(open(path).read()), re.M)}
def links(path):
    text = prose(open(path).read())
    return re.findall(r"(?<!!)\[[^\]]*\]\(([^)\s]+)\)", text) + re.findall(r"^\[[^\]]+\]:\s*(\S+)", text, re.M)
def problems(skill_dir):
