        out.append(f"name {meta.get('name')!r} != directory")
    d = meta.get("description")
    if not isinstance(d, str) or not d.strip() or len(d) > 1024:
        out.append("description missing or over 1024 characters")
    linked = {os.path.normpath(os.path.join(skill_dir, l.split("#")[0])) for l in links(skill_md) if not re.match(r"[a-z]+:", l) and l.split("#")[0]}
    refs = []
    for root, _, names in os.walk(os.path.join(skill_dir, "references")):
        refs += [os.path.join(root, n) for n in names if n.endswith(".md")]
    for r in refs:
        if os.path.normpath(r) not in linked:
            out.append(f"{r}: not linked from SKILL.md")
        text = open(r).read()
        if text.count("\n") > 100 and not re.search(r"^## Contents\s*$", text, re.M):
            out.append(f"{r}: over 100 lines without ## Contents")
    for src in [skill_md] + refs:
        for l in links(src):
            if re.match(r"[a-z]+:", l):
                continue
            target, _, anchor = l.partition("#")
            tpath = os.path.normpath(os.path.join(os.path.dirname(src), target)) if target else src
            if not os.path.exists(tpath):
                out.append(f"{src}: broken link {l}"); continue
            if anchor and tpath.endswith(".md") and anchor not in anchors(tpath):
                out.append(f"{src}: missing anchor {l}")
    return out

